    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65

    # Vertical impulse: apply upward impulse when moving downward (bottom of swing)
    if pos.y < target_y and vy < 0:
        # Apply upward impulse (maximum allowed)
        sandbox.apply_impulse_to_seat(0, 4.2)
    elif pos.y >= target_y:
        # Apply damping to slow descent
        vertical_force = -vy * 5  # Moderated damping force
    else:
        vertical_force = 0

    # Horizontal force: pump towards the pivot and counteract wind
    if pos.x < 10.0:
        # To the left of pivot, push right
        if vx > 0:
            horizontal_force = 42.0
        elif vx < 0:
            horizontal_force = -42.0
        else:
            horizontal_force = 0
    elif pos.x > 10.0:
        # To the right of pivot, push left
        if vx < 0:
            horizontal_force = -42.0
        elif vx > 0:
            horizontal_force = 42.0
        else:
            horizontal_force = 0
    else:
        horizontal_force = 0

    # Adjust horizontal force to counteract wind direction (estimate based on velocity)
    # Wind may be blowing in the opposite direction of motion, so apply force in the direction of motion
    # This is a heuristic to counteract wind, assuming wind opposes the desired motion
    wind_compensation = -vx * 10  # Adjust multiplier to balance wind and swing
